// ─── File: TxSyncDemo.java ───
// Runnable demo that simulates Spring's TransactionSynchronization lifecycle.
// It shows beforeCommit, afterCommit, beforeCompletion and afterCompletion
// firing in the correct order for a successful and a failing transfer.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TxSyncDemo {
    private static final Logger log = Logger.getLogger("BankTxSync");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        NotificationService notifier = new NotificationService(log);
        BalanceCache cache = new BalanceCache(log);
        TransferService service = new TransferService(repo, notifier, cache, log);

        log.info(() -> "=== Successful transfer: Rs.50000 SAV2001 -> CUR3001 ===");
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        log.info(() -> "=== Failing transfer: Rs.9999999 SAV2001 -> CUR3001 ===");
        try {
            service.transfer("SAV2001", "CUR3001", new BigDecimal("9999999"));
        } catch (RuntimeException ex) {
            log.warning(() -> "Caller saw failure: " + ex.getMessage());
        }

        log.info(() -> "FINAL Rajesh = " + repo.findById("SAV2001").getBalance()
                      + ", Priya = " + repo.findById("CUR3001").getBalance());
    }
}

// ─── model/Account.java ───
class Account {
    private final String accountId; private final String holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
    BigDecimal totalMoney() {
        return store.values().stream().map(Account::getBalance)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

// ─── service/NotificationService.java — external side effect, must run AFTER commit ───
class NotificationService {
    private final Logger log;
    NotificationService(Logger log) { this.log = log; }
    void sendSms(String holder, String message) {
        log.info(() -> "SMS to " + holder + ": " + message);
    }
}

// ─── service/BalanceCache.java — must be cleared AFTER completion, pass or fail ───
class BalanceCache {
    private final Map<String, BigDecimal> cache = new HashMap<>();
    private final Logger log;
    BalanceCache(Logger log) { this.log = log; }
    void put(String id, BigDecimal bal) { cache.put(id, bal); }
    void evict(String id) { cache.remove(id); log.fine(() -> "Cache evicted for " + id); }
}

// ─── sync/TransferSynchronization.java — the four lifecycle callbacks ───
// In real Spring this implements org.springframework.transaction.support.TransactionSynchronization.
// Here we mirror the same four methods and status constants for a runnable demo.
class TransferSynchronization {
    static final int STATUS_COMMITTED = 0;
    static final int STATUS_ROLLED_BACK = 1;

    private final AccountRepository repo;
    private final NotificationService notifier;
    private final BalanceCache cache;
    private final Logger log;
    private final String from; private final String to; private final BigDecimal amount;
    private final BigDecimal expectedTotal;

    TransferSynchronization(AccountRepository repo, NotificationService notifier, BalanceCache cache,
                            Logger log, String from, String to, BigDecimal amount, BigDecimal expectedTotal) {
        this.repo=repo; this.notifier=notifier; this.cache=cache; this.log=log;
        this.from=from; this.to=to; this.amount=amount; this.expectedTotal=expectedTotal;
    }

    // Runs just before commit — last chance to enforce an invariant.
    void beforeCommit(boolean readOnly) {
        BigDecimal total = repo.totalMoney();
        log.fine(() -> "beforeCommit: total money = " + total + " (expected " + expectedTotal + ")");
        if (total.compareTo(expectedTotal) != 0) {
            throw new IllegalStateException("Ledger not balanced — aborting commit");
        }
    }

    // Runs just before the transaction ends, pass or fail.
    void beforeCompletion() {
        log.fine(() -> "beforeCompletion: releasing transfer resources");
    }

    // Runs ONLY after a successful commit — safe place for the SMS.
    void afterCommit() {
        notifier.sendSms(repo.findById(from).getHolderName(),
            "Rs." + amount + " transferred to " + to + " successfully");
    }

    // Always runs at the end — clear cache no matter the outcome.
    void afterCompletion(int status) {
        cache.evict(from);
        cache.evict(to);
        if (status == STATUS_ROLLED_BACK) {
            log.severe(() -> "afterCompletion: transfer ROLLED BACK, no SMS sent");
        } else {
            log.info(() -> "afterCompletion: transfer COMMITTED cleanly");
        }
    }
}

// ─── service/TransferService.java — runs transfer and registers the synchronization ───
class TransferService {
    private final AccountRepository repo;
    private final NotificationService notifier;
    private final BalanceCache cache;
    private final Logger log;

    TransferService(AccountRepository repo, NotificationService notifier, BalanceCache cache, Logger log) {
        this.repo=repo; this.notifier=notifier; this.cache=cache; this.log=log;
    }

    // @Transactional in real Spring. The runner below plays the role of the proxy.
    void transfer(String from, String to, BigDecimal amount) {
        BigDecimal expectedTotal = repo.totalMoney(); // total must not change, only move
        TransferSynchronization sync = new TransferSynchronization(
            repo, notifier, cache, log, from, to, amount, expectedTotal);

        TxRunner.run(log, sync, () -> {
            Account f = repo.findById(from);
            Account t = repo.findById(to);
            if (f.getBalance().compareTo(amount) < 0)
                throw new IllegalStateException("Insufficient balance in " + from);
            f.debit(amount);
            t.credit(amount);
            cache.put(from, f.getBalance());
            cache.put(to, t.getBalance());
            log.info(() -> "transfer body applied " + from + "->" + to + " Rs." + amount);
        });
    }
}

// ─── A tiny transaction runner that fires callbacks in Spring's real order ───
// Spring order: body -> beforeCommit -> beforeCompletion -> COMMIT -> afterCommit -> afterCompletion
// On failure: body throws -> beforeCompletion -> ROLLBACK -> afterCompletion(ROLLED_BACK)
class TxRunner {
    static void run(Logger log, TransferSynchronization sync, Runnable body) {
        log.fine(() -> "TX BEGIN");
        try {
            body.run();
            sync.beforeCommit(false);
            sync.beforeCompletion();
            log.fine(() -> "TX COMMIT");
            sync.afterCommit();
            sync.afterCompletion(TransferSynchronization.STATUS_COMMITTED);
        } catch (RuntimeException ex) {
            sync.beforeCompletion();
            log.severe(() -> "TX ROLLBACK (" + ex.getMessage() + ")");
            sync.afterCompletion(TransferSynchronization.STATUS_ROLLED_BACK);
            throw ex;
        }
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
