The real Spring structure registers the synchronization inside the transactional method:

```java
// ─── File: src/main/java/com/bank/txsync/service/TransferService.java ───
package com.bank.txsync.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import java.math.BigDecimal;

@Service
public class TransferService {
    private final AccountRepository repo;
    private final NotificationService notifier;

    public TransferService(AccountRepository repo, NotificationService notifier) {
        this.repo = repo; this.notifier = notifier;
    }

    @Transactional
    public void transfer(String from, String to, BigDecimal amount) {
        var f = repo.findById(from).orElseThrow();
        var t = repo.findById(to).orElseThrow();
        if (f.getBalance().compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient balance");
        f.debit(amount); t.credit(amount);
        repo.save(f); repo.save(t);

        // Only register when a real transaction is active.
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override public void afterCommit() {
                    notifier.sendSms(f.getHolderName(), "Rs." + amount + " transferred to " + to);
                }
                @Override public void afterCompletion(int status) {
                    if (status == STATUS_ROLLED_BACK) { /* metrics, no SMS */ }
                }
            });
        }
    }
}
